hkdf.pseudocode:
def hkdf_extract(salt, ikm):
    if not salt:
        salt = bytes(HASH_LEN)  # 솔트 없으면 0으로 채움
    return hmac(salt, ikm)  # PRK

def hkdf_expand(prk, info, length):
    n = ceil(length / HASH_LEN)  # 최대 255블록
    t, okm = b'', b''
    for i in range(1, n + 1):
        # T(i) = HMAC(PRK, T(i-1) ‖ info ‖ i)
        t = hmac(prk, t + info + bytes([i]))
        okm += t
    return okm[:length]
